insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$uruka$t$, $t$Uruka$t$, $t$উৰুকা$t$, $t$The night before Magh (Bhogali) Bihu, spent feasting and staying awake around a bonfire.$t$, $t$মাঘ (ভোগালী) বিহুৰ আগৰ নিশা, যিটো ভোজ-ভাত খাই আৰু মেজিৰ কাষত সাৰে থাকি পাৰ কৰা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$meji$t$, $t$Meji$t$, $t$মেজি$t$, $t$The bonfire built for Magh Bihu and burnt early on the morning of the festival.$t$, $t$মাঘ বিহুৰ বাবে সজা জুইৰ ঘৰ, যিটো বিহুৰ দিনা ৰাতিপুৱা জ্বলোৱা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$bhelaghar$t$, $t$Bhelaghar$t$, $t$ভেলাঘৰ$t$, $t$A temporary hut of straw and bamboo built by young people for the Uruka night feast.$t$, $t$উৰুকাৰ ভোজৰ বাবে ডেকা-গাভৰুৱে খেৰ আৰু বাঁহেৰে সজা অস্থায়ী ঘৰ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$husori$t$, $t$Husori$t$, $t$হুচৰি$t$, $t$Groups who go from house to house during Bohag Bihu singing songs and blessing each family.$t$, $t$বহাগ বিহুৰ সময়ত ঘৰে ঘৰে গৈ গীত গাই প্ৰতিটো পৰিয়ালক আশীৰ্বাদ দিয়া দল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$bihuwan$t$, $t$Bihuwan$t$, $t$বিহুৱান$t$, $t$A gift, usually a gamosa, given to elders and loved ones at Bohag Bihu.$t$, $t$বহাগ বিহুত ডাঙৰ আৰু মৰমৰ মানুহক দিয়া উপহাৰ, সাধাৰণতে এখন গামোচা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$sattra$t$, $t$Sattra$t$, $t$সত্ৰ$t$, $t$A monastery-like centre of Sankardev's Neo-Vaishnavite faith, for prayer, music, dance and learning.$t$, $t$শংকৰদেৱৰ নৱ-বৈষ্ণৱ ধৰ্মৰ উপাসনা, গীত-মাত, নৃত্য আৰু শিক্ষাৰ মঠসদৃশ কেন্দ্ৰ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$namghar$t$, $t$Namghar$t$, $t$নামঘৰ$t$, $t$A prayer hall where people gather to sing and pray. Every Sattra has one, and most Assamese villages too.$t$, $t$মানুহ গোট খাই নাম-প্ৰসংগ কৰা উপাসনা গৃহ। প্ৰতিখন সত্ৰত আৰু বেছিভাগ অসমীয়া গাঁৱতো নামঘৰ থাকে।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$satradhikar$t$, $t$Satradhikar$t$, $t$সত্ৰাধিকাৰ$t$, $t$The head of a Sattra.$t$, $t$সত্ৰৰ মুৰব্বী।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$ankiya-naat$t$, $t$Ankiya Naat$t$, $t$অংকীয়া নাট$t$, $t$One-act plays created by Sankardev. Their stage performance is called Bhaona.$t$, $t$শংকৰদেৱে সৃষ্টি কৰা এক অংকৰ নাট। ইয়াৰ মঞ্চ পৰিৱেশনক ভাওনা বোলা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$borgeet$t$, $t$Borgeet$t$, $t$বৰগীত$t$, $t$Devotional songs composed by Sankardev and Madhavdev.$t$, $t$শংকৰদেৱ আৰু মাধৱদেৱে ৰচনা কৰা ভক্তিমূলক গীত।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$classical-dance$t$, $t$Classical dance$t$, $t$শাস্ত্ৰীয় নৃত্য$t$, $t$A dance form recognised by the Sangeet Natak Akademi for its old, rule-based tradition. Sattriya is one of them.$t$, $t$প্ৰাচীন আৰু নিয়মবদ্ধ পৰম্পৰাৰ বাবে সংগীত নাটক অকাডেমীয়ে স্বীকৃতি দিয়া নৃত্য। সত্ৰীয়া তাৰে এটা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$geographical-indication$t$, $t$Geographical Indication (GI) tag$t$, $t$ভৌগোলিক সূচক (জি আই) চিহ্ন$t$, $t$An official label showing that a product comes from a particular place and has qualities linked to it.$t$, $t$কোনো সামগ্ৰী এটা নিৰ্দিষ্ট ঠাইৰ আৰু তাৰ গুণ সেই ঠাইৰ সৈতে জড়িত বুলি দেখুওৱা চৰকাৰী স্বীকৃতি।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$charyapada$t$, $t$Charyapada$t$, $t$চৰ্যাপদ$t$, $t$Buddhist songs of about the 8th to 10th century, taken as the earliest examples of Assamese literature.$t$, $t$প্ৰায় অষ্টমৰ পৰা দশম শতিকাৰ বৌদ্ধ গীত, যাক অসমীয়া সাহিত্যৰ আটাইতকৈ পুৰণি নিদৰ্শন বুলি ধৰা হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$buranji$t$, $t$Buranji$t$, $t$বুৰঞ্জী$t$, $t$Prose chronicles of the Ahom court that recorded events and history.$t$, $t$ঘটনা আৰু ইতিহাস লিপিবদ্ধ কৰা আহোম ৰাজসভাৰ গদ্য ইতিহাস গ্ৰন্থ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$jonaki-era$t$, $t$Jonaki era$t$, $t$জোনাকী যুগ$t$, $t$The start of modern Assamese literature, named after the magazine Jonaki (1889).$t$, $t$আধুনিক অসমীয়া সাহিত্যৰ আৰম্ভণি, জোনাকী (১৮৮৯) আলোচনীৰ নামেৰে নামকৰণ কৰা।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$jnanpith-award$t$, $t$Jnanpith Award$t$, $t$জ্ঞানপীঠ বঁটা$t$, $t$India's highest literary award, given every year to a writer in an Indian language.$t$, $t$ভাৰতীয় ভাষাৰ এগৰাকী সাহিত্যিকক প্ৰতি বছৰে দিয়া দেশৰ সৰ্বোচ্চ সাহিত্য বঁটা।$t$) on conflict (slug) do nothing;
insert into public.content (slug, kind, category_id, position) select $t$bihu$t$, 'gk_chapter', id, 1 from public.categories where slug = $t$culture$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Bihu$t$, $t$The three Bihus of Assam and the customs of each.$t$, 'draft', $t$Bihu, Wikipedia: https://en.wikipedia.org/wiki/Bihu$t$, date '2026-11-24' from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Bihu is the main festival of Assam and its state festival. There are three Bihus in the year, linked to the farming cycle.$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'heritage', $t$Rongali or Bohag Bihu (April): the spring festival and the Assamese New Year. It is the most important Bihu.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Bohag Bihu$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$The first day, Goru Bihu (usually 14 April), is for cattle: they are washed and smeared with turmeric. The next day, Manuh Bihu, is New Year's Day, when people give a {{term:bihuwan}} to elders. {{term:husori|Husori}} groups then go singing from house to house.$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 5, 'heading', 'normal', $t$Magh Bihu$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 6, 'paragraph', 'normal', $t$On {{term:uruka}} night, young people build a {{term:bhelaghar}} and a {{term:meji}}, and feast together. The Meji is burnt the next morning.$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$The Bihu dance is the state dance. It is played with the dhol, the pepa (buffalo-horn pipe) and the taal (cymbals).$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Rongali = Bohag (April), Kongali = Kati (Oct/Nov), Bhogali = Magh (January).$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$বিহু$t$, $t$অসমৰ তিনিটা বিহু আৰু প্ৰতিটোৰ ৰীতি-নীতি।$t$, 'draft', $t$Bihu, Wikipedia: https://en.wikipedia.org/wiki/Bihu$t$, date '2026-11-24' from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$বিহু অসমৰ প্ৰধান উৎসৱ আৰু ৰাজ্যিক উৎসৱ। বছৰত তিনিটা বিহু হয়, যিবোৰ কৃষিচক্ৰৰ সৈতে জড়িত।$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'heritage', $t$ৰঙালী বা বহাগ বিহু (এপ্ৰিল): বসন্তৰ উৎসৱ আৰু অসমীয়া নৱবৰ্ষ। ই আটাইতকৈ গুৰুত্বপূৰ্ণ বিহু।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$বহাগ বিহু$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$প্ৰথম দিনটো গৰু বিহু (সাধাৰণতে ১৪ এপ্ৰিল): গৰুক গা ধুৱাই হালধি-মাহ লগোৱা হয়। পিছদিনা মানুহ বিহু, নৱবৰ্ষৰ দিন, যেতিয়া ডাঙৰসকলক {{term:bihuwan|বিহুৱান}} দিয়া হয়। তাৰ পিছত {{term:husori|হুচৰিৰ}} দলে ঘৰে ঘৰে গীত গাই ফুৰে।$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 5, 'heading', 'normal', $t$মাঘ বিহু$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 6, 'paragraph', 'normal', $t${{term:uruka|উৰুকাৰ}} নিশা ডেকা-গাভৰুৱে {{term:bhelaghar|ভেলাঘৰ}} আৰু {{term:meji|মেজি}} সাজি একেলগে ভোজ খায়। পিছদিনা ৰাতিপুৱা মেজি জ্বলোৱা হয়।$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$বিহু নাচ ৰাজ্যিক নৃত্য। ইয়াত ঢোল, পেঁপা (ম'হৰ শিঙৰ বাদ্য) আৰু তাল বজোৱা হয়।$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ৰঙালী = বহাগ (এপ্ৰিল), কঙালী = কাতি (অক্টো/নৱে), ভোগালী = মাঘ (জানুৱাৰী)।$t$ from public.content where slug = $t$bihu$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$sattriya-and-sattra$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$culture$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Sattriya dance and the Sattra institution$t$, $t$The Sattras founded in Sankardev's tradition, and the classical dance that grew in them.$t$, 'draft', $t$Satra, Wikipedia: https://en.wikipedia.org/wiki/Sattra
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$A {{term:sattra}} is a centre of the {{term:neo-vaishnavism|Neo-Vaishnavite}} faith started by Srimanta Sankardev. Sankardev is said to have set up his first Sattra at Bordowa, his birthplace.$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$Every Sattra has a {{term:namghar}} (also called kirtanghar), its prayer hall. Each Sattra is headed by a {{term:satradhikar}}. The Asam Satra Mahasabha counts 862 Sattras in Assam and West Bengal.$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'heritage', $t$Majuli became the main centre of the Sattra tradition. Well-known Sattras include Auniati, Dakhinpat, Garamur and Kamalabari in Majuli, and the Barpeta Sattra, built by Madhavdev.$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 4, 'heading', 'normal', $t$Sattriya dance$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$Sattriya dance was created by Sankardev as part of Bhaona, the stage performance of his {{term:ankiya-naat|Ankiya Naat}}. It was kept alive in the Sattras for centuries.$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 6, 'paragraph', 'event', $t$On 15 November 2000, the Sangeet Natak Akademi recognised Sattriya as one of the eight {{term:classical-dance|classical dances}} of India.$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: first Sattra at Bordowa; Sattriya recognised as a classical dance on 15 November 2000.$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$সত্ৰীয়া নৃত্য আৰু সত্ৰ অনুষ্ঠান$t$, $t$শংকৰদেৱৰ পৰম্পৰাত প্ৰতিষ্ঠিত সত্ৰ, আৰু তাত গঢ় লোৱা শাস্ত্ৰীয় নৃত্য।$t$, 'draft', $t$Satra, Wikipedia: https://en.wikipedia.org/wiki/Sattra
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:sattra|সত্ৰ}} শ্ৰীমন্ত শংকৰদেৱে প্ৰৱৰ্তন কৰা {{term:neo-vaishnavism|নৱ-বৈষ্ণৱ}} ধৰ্মৰ কেন্দ্ৰ। কোৱা হয় যে শংকৰদেৱে তেওঁৰ জন্মস্থান বৰদোৱাত প্ৰথম সত্ৰ স্থাপন কৰিছিল।$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$প্ৰতিখন সত্ৰত এটা {{term:namghar|নামঘৰ}} (কীৰ্তনঘৰ বুলিও কোৱা হয়) থাকে। প্ৰতিখন সত্ৰৰ মুৰব্বী এগৰাকী {{term:satradhikar|সত্ৰাধিকাৰ}}। অসম সত্ৰ মহাসভাৰ হিচাপমতে অসম আৰু পশ্চিমবংগত ৮৬২ খন সত্ৰ আছে।$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'heritage', $t$মাজুলী সত্ৰ পৰম্পৰাৰ মূল কেন্দ্ৰ হৈ পৰে। জনাজাত সত্ৰসমূহৰ ভিতৰত মাজুলীৰ আউনীআটী, দক্ষিণপাট, গড়মূৰ আৰু কমলাবাৰী, আৰু মাধৱদেৱে নিৰ্মাণ কৰা বৰপেটা সত্ৰ উল্লেখযোগ্য।$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 4, 'heading', 'normal', $t$সত্ৰীয়া নৃত্য$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$শংকৰদেৱে তেওঁৰ {{term:ankiya-naat|অংকীয়া নাটৰ}} মঞ্চ পৰিৱেশন ভাওনাৰ অংশ হিচাপে সত্ৰীয়া নৃত্য সৃষ্টি কৰিছিল। শতিকাজুৰি সত্ৰসমূহে ইয়াক জীয়াই ৰাখে।$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 6, 'paragraph', 'event', $t$২০০০ চনৰ ১৫ নৱেম্বৰত সংগীত নাটক অকাডেমীয়ে সত্ৰীয়াক ভাৰতৰ আঠটা {{term:classical-dance|শাস্ত্ৰীয় নৃত্যৰ}} এটা হিচাপে স্বীকৃতি দিয়ে।$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: প্ৰথম সত্ৰ বৰদোৱাত; ১৫ নৱেম্বৰ ২০০০ত সত্ৰীয়াই শাস্ত্ৰীয় নৃত্যৰ স্বীকৃতি পায়।$t$ from public.content where slug = $t$sattriya-and-sattra$t$ on conflict do nothing;
