insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Folk dances and music$t$, $t$Bagurumba, Ojapali, Borgeet and other dance and music traditions of Assam.$t$, 'draft', $t$Bagurumba, Wikipedia: https://en.wikipedia.org/wiki/Bagurumba
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Each community of Assam has its own dances and songs. These are the ones most often asked about:$t$ from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
