insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$ভক্তিমূলক সংগীত$t$ from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t${{term:borgeet|বৰগীত}} শংকৰদেৱ আৰু মাধৱদেৱে ৰচনা কৰা ভক্তিমূলক গীত। মাধৱদেৱে অকলেই ১৯১ টা বৰগীত ৰচনা কৰিছিল।$t$ from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$ওজাপালিৰ কেইবাটাও ৰূপ আছে: মহাকাব্যভিত্তিক ব্যাহ (ব্যাস) ওজাপালি, মনসা দেৱীৰ সৈতে জড়িত সুকনান্নি (মাৰৈ) ওজাপালি, ৰামায়ণী ওজাপালি আৰু সত্ৰীয়া ওজাপালি।$t$ from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 6, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: বাগৰুম্বা = বড়োসকলৰ পখিলা নৃত্য; ওজাপালি = ওজা আৰু পালি, কেন্দ্ৰ দৰং জিলা।$t$ from public.content where slug = $t$folk-dances-and-music$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$silk-and-handloom$t$, 'gk_chapter', id, 4 from public.categories where slug = $t$culture$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Silk and handloom$t$, $t$Muga, Eri and Pat silk, the gamosa, and Sualkuchi, the weaving town.$t$, 'draft', $t$Muga silk, Wikipedia: https://en.wikipedia.org/wiki/Muga_silk
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Weaving is part of daily life in Assam, and the state is famous for three kinds of silk: Muga, Eri and Pat.$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Muga, the golden silk$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'heritage', $t${{term:muga-silk|Muga silk}} has a natural yellowish-golden shine and is produced only in Assam. It comes from the Muga silkworm (Antheraea assamensis), which feeds on Som and Sualu leaves. Muga received a {{term:geographical-indication|GI tag}} in 2007.$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 4, 'heading', 'normal', $t$The gamosa$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$The gamosa is a white cloth with red borders. The word means 'something to wipe the body with', but it is much more than a towel: it is offered to guests, given as bihuwan, worn by Bihu dancers and used to cover the scriptures in the namghar. The gamosa of Assam received a GI tag on 13 December 2022.$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h3', 6, 'heading', 'normal', $t$Sualkuchi$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$Sualkuchi, on the north bank of the Brahmaputra in Kamrup district, about 35 km from Guwahati, is a famous silk-weaving town. It is known as the 'Manchester of Assam'.$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Muga GI tag 2007; Gamosa GI tag 2022; Sualkuchi = Manchester of Assam.$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$পাট-মুগা আৰু তাঁতশাল$t$, $t$মুগা, এৰী আৰু পাট, গামোচা, আৰু বোৱা-কটাৰ নগৰ শোৱালকুছি।$t$, 'draft', $t$Muga silk, Wikipedia: https://en.wikipedia.org/wiki/Muga_silk
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমত বোৱা-কটা দৈনন্দিন জীৱনৰ অংশ, আৰু ৰাজ্যখন তিনি প্ৰকাৰৰ পাটৰ বাবে বিখ্যাত: মুগা, এৰী আৰু পাট।$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$মুগা, সোণালী পাট$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'heritage', $t${{term:muga-silk|মুগাৰ}} এক প্ৰাকৃতিক সোণালী-হালধীয়া চিকমিকনি আছে আৰু ই কেৱল অসমতহে উৎপাদন হয়। ই মুগা পলুৰ (Antheraea assamensis) পৰা পোৱা যায়, যিয়ে সোম আৰু চোৱালু পাত খায়। ২০০৭ চনত মুগাই {{term:geographical-indication|জি আই চিহ্ন}} লাভ কৰে।$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 4, 'heading', 'normal', $t$গামোচা$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$গামোচা ৰঙা আঁচুৰে বগা কাপোৰ। শব্দটোৰ অৰ্থ 'গা মচা বস্তু', কিন্তু ই কেৱল গা মচা কাপোৰ নহয়: ইয়াৰে অতিথিক সন্মান জনোৱা হয়, বিহুৱান হিচাপে দিয়া হয়, বিহুৱতীয়ে পিন্ধে আৰু নামঘৰত পুথি ঢাকিবলৈ ব্যৱহাৰ কৰা হয়। ২০২২ চনৰ ১৩ ডিচেম্বৰত অসমৰ গামোচাই জি আই চিহ্ন লাভ কৰে।$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h3', 6, 'heading', 'normal', $t$শোৱালকুছি$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$কামৰূপ জিলাত, ব্ৰহ্মপুত্ৰৰ উত্তৰ পাৰত, গুৱাহাটীৰ পৰা প্ৰায় ৩৫ কিমি দূৰত থকা শোৱালকুছি পাট-মুগা বোৱাৰ বাবে বিখ্যাত। ইয়াক 'অসমৰ মেনচেষ্টাৰ' বুলি কোৱা হয়।$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: মুগাৰ জি আই ২০০৭; গামোচাৰ জি আই ২০২২; শোৱালকুছি = অসমৰ মেনচেষ্টাৰ।$t$ from public.content where slug = $t$silk-and-handloom$t$ on conflict do nothing;
