insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assamese literature can be traced back to the {{term:charyapada|Charyapada}}, Buddhist songs of about the 8th to 10th century.$t$ from public.content where slug = $t$assamese-literature$t$ on conflict do nothing;
