insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 9, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: তিনিগৰাকী অসমীয়া সাহিত্যিকে {{term:jnanpith-award|জ্ঞানপীঠ বঁটা}} পাইছে: বীৰেন্দ্ৰ কুমাৰ ভট্টাচাৰ্য (১৯৭৯), মামণি ৰয়ছম গোস্বামী (২০০০) আৰু নীলমণি ফুকন (২০২০)।$t$ from public.content where slug = $t$assamese-literature$t$ on conflict do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$national-park$t$, $t$National park$t$, $t$ৰাষ্ট্ৰীয় উদ্যান$t$, $t$A protected area where wildlife and nature are fully protected by law. People may not live, graze cattle or cut trees inside.$t$, $t$আইনৰ দ্বাৰা বন্যপ্ৰাণী আৰু প্ৰকৃতি সম্পূৰ্ণৰূপে সুৰক্ষিত এলেকা। ইয়াৰ ভিতৰত বসতি, গৰু চৰোৱা বা গছ কটা নিষেধ।$t$) on conflict (slug) do nothing;
