insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam has eight {{term:national-park|national parks}}. These are listed with the year each became a national park:$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
