insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Kaziranga National Park$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'verified_fact', $t$Kaziranga lies mainly in Golaghat and Nagaon districts. In 1904 Mary Curzon, wife of the Viceroy, visited it but could not see a rhino, and urged her husband to protect it. It became a reserve forest on 1 June 1905 and a national park on 11 February 1974. UNESCO declared it a {{term:world-heritage-site|World Heritage Site}} in 1985.$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 5, 'heading', 'normal', $t$Manas National Park$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 6, 'paragraph', 'verified_fact', $t$Manas, named after the Manas river, lies on the border with Bhutan, next to Bhutan's Royal Manas National Park. It became a sanctuary on 1 October 1928, a biosphere reserve in 1989 and a World Heritage Site in 1985. UNESCO listed it as 'in danger' in 1992 and removed it from that list on 21 June 2011.$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$Manas is home to the {{term:pygmy-hog|pygmy hog}}, the smallest wild pig in the world, and the {{term:golden-langur|golden langur}}.$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: Kaziranga and Manas are both World Heritage Sites (1985). Newest national park: Sikna Jwhwlao (2024).$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ ৰাষ্ট্ৰীয় উদ্যানসমূহ$t$, $t$কাজিৰঙাৰ পৰা চিকনা ঝাওলাওলৈ অসমৰ আঠখন ৰাষ্ট্ৰীয় উদ্যান আৰু সেইবোৰ ঘোষণাৰ বছৰ।$t$, 'draft', $t$List of protected areas of Assam, Wikipedia: https://en.wikipedia.org/wiki/List_of_protected_areas_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমত আঠখন {{term:national-park|ৰাষ্ট্ৰীয় উদ্যান}} আছে। প্ৰতিখন ৰাষ্ট্ৰীয় উদ্যান হিচাপে ঘোষিত হোৱাৰ বছৰৰ সৈতে তালিকাখন এনেধৰণৰ:$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'geography', $t$কাজিৰঙা: ১৯৭৪
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 3, 'heading', 'normal', $t$কাজিৰঙা ৰাষ্ট্ৰীয় উদ্যান$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'verified_fact', $t$কাজিৰঙা মূলতঃ গোলাঘাট আৰু নগাঁও জিলাত অৱস্থিত। ১৯০৪ চনত ভাইচৰয়ৰ পত্নী মেৰী কাৰ্জনে ইয়ালৈ আহি গঁড় দেখা নাপালে, আৰু ইয়াক সুৰক্ষা দিবলৈ স্বামীক অনুৰোধ কৰে। ১৯০৫ চনৰ ১ জুনত ই সংৰক্ষিত বনাঞ্চল আৰু ১৯৭৪ চনৰ ১১ ফেব্ৰুৱাৰীত ৰাষ্ট্ৰীয় উদ্যান হয়। ১৯৮৫ চনত ইউনেস্কোৱে ইয়াক {{term:world-heritage-site|বিশ্ব ঐতিহ্য ক্ষেত্ৰ}} ঘোষণা কৰে।$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 5, 'heading', 'normal', $t$মানাহ ৰাষ্ট্ৰীয় উদ্যান$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 6, 'paragraph', 'verified_fact', $t$মানাহ নদীৰ নামেৰে নামকৰণ কৰা মানাহ ভূটানৰ সীমাত, ভূটানৰ ৰয়েল মানাহ ৰাষ্ট্ৰীয় উদ্যানৰ কাষত অৱস্থিত। ১৯২৮ চনৰ ১ অক্টোবৰত ই অভয়াৰণ্য, ১৯৮৯ চনত জৈৱমণ্ডল সংৰক্ষিত ক্ষেত্ৰ আৰু ১৯৮৫ চনত বিশ্ব ঐতিহ্য ক্ষেত্ৰ হয়। ১৯৯২ চনত ইউনেস্কোৱে ইয়াক 'বিপদগ্ৰস্ত' তালিকাত ৰাখে আৰু ২০১১ চনৰ ২১ জুনত সেই তালিকাৰ পৰা আঁতৰায়।$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$মানাহত পৃথিৱীৰ আটাইতকৈ সৰু বনৰীয়া গাহৰি {{term:pygmy-hog|নল গাহৰি}} আৰু {{term:golden-langur|সোণালী বান্দৰ}} পোৱা যায়।$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: কাজিৰঙা আৰু মানাহ দুয়োখন বিশ্ব ঐতিহ্য ক্ষেত্ৰ (১৯৮৫)। আটাইতকৈ নতুন ৰাষ্ট্ৰীয় উদ্যান: চিকনা ঝাওলাও (২০২৪)।$t$ from public.content where slug = $t$national-parks-of-assam$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$one-horned-rhinoceros$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$wildlife$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The one-horned rhinoceros$t$, $t$Assam's state animal: how many there are, where they live and what threatens them.$t$, 'draft', $t$Indian rhinoceros, Wikipedia: https://en.wikipedia.org/wiki/Indian_rhinoceros
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The {{term:one-horned-rhinoceros|one-horned rhinoceros}} (scientific name Rhinoceros unicornis) is the state animal of Assam. The IUCN lists it as {{term:iucn-vulnerable|Vulnerable}}.$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'verified_fact', $t$A census in March 2025 counted 4,075 wild rhinos: 3,323 in India and 752 in Nepal. In 2006 there were only 2,577.$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'normal', $t$More than 70 percent of all one-horned rhinos live in a single place, Kaziranga National Park. Pobitora Wildlife Sanctuary in Morigaon district has one of the largest rhino populations in Assam in a small area of about 38.8 sq km.$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 4, 'heading', 'normal', $t$Threats$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$The main threat is {{term:poaching}} for the horn, which is used in traditional Chinese medicine. Floods, loss of grassland and invasive plants are other threats.$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 6, 'paragraph', 'normal', $t$Under the Indian Rhino Vision 2020 programme, rhinos from Kaziranga were moved to other parks such as Manas to build new populations.$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: Rhinoceros unicornis; IUCN status Vulnerable; over 70% live in Kaziranga.$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$এশিঙীয়া গঁড়$t$, $t$অসমৰ ৰাজ্যিক জন্তু: সংখ্যা কিমান, ক'ত থাকে আৰু কি বিপদৰ সন্মুখীন।$t$, 'draft', $t$Indian rhinoceros, Wikipedia: https://en.wikipedia.org/wiki/Indian_rhinoceros
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:one-horned-rhinoceros|এশিঙীয়া গঁড়}} (বৈজ্ঞানিক নাম Rhinoceros unicornis) অসমৰ ৰাজ্যিক জন্তু। আই ইউ চি এনে ইয়াক {{term:iucn-vulnerable|বিপদাপন্ন}} প্ৰজাতি হিচাপে তালিকাভুক্ত কৰিছে।$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'verified_fact', $t$২০২৫ চনৰ মাৰ্চ মাহৰ লোকপিয়লত বনত ৪,০৭৫ টা গঁড় গণনা কৰা হয়: ভাৰতত ৩,৩২৩ আৰু নেপালত ৭৫২। ২০০৬ চনত মাত্ৰ ২,৫৭৭ টা আছিল।$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'normal', $t$সকলো এশিঙীয়া গঁড়ৰ ৭০ শতাংশতকৈ বেছি একেটা ঠাইতে থাকে, সেয়া হ'ল কাজিৰঙা ৰাষ্ট্ৰীয় উদ্যান। মৰিগাঁও জিলাৰ পবিতৰা বন্যপ্ৰাণী অভয়াৰণ্যত প্ৰায় ৩৮.৮ বৰ্গ কিমিৰ সৰু এলেকাত অসমৰ আটাইতকৈ ডাঙৰ গঁড়ৰ সমষ্টিসমূহৰ এটা আছে।$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 4, 'heading', 'normal', $t$বিপদসমূহ$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$মূল বিপদ হৈছে খড়গৰ বাবে {{term:poaching|চোৰাং চিকাৰ}}; খড়গ পৰম্পৰাগত চীনা ঔষধত ব্যৱহাৰ হয়। বানপানী, তৃণভূমিৰ ক্ষয় আৰু আগ্ৰাসী উদ্ভিদো আন বিপদ।$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 6, 'paragraph', 'normal', $t$ইণ্ডিয়ান ৰাইন' ভিজন ২০২০ কাৰ্যসূচীৰ অধীনত কাজিৰঙাৰ পৰা গঁড় মানাহৰ দৰে আন উদ্যানলৈ স্থানান্তৰ কৰি নতুন সমষ্টি গঢ়া হয়।$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: Rhinoceros unicornis; আই ইউ চি এন স্থিতি বিপদাপন্ন; ৭০%তকৈ বেছি কাজিৰঙাত থাকে।$t$ from public.content where slug = $t$one-horned-rhinoceros$t$ on conflict do nothing;
