insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam has 17 {{term:wildlife-sanctuary|wildlife sanctuaries}}. These are some of the best known:$t$ from public.content where slug = $t$wildlife-sanctuaries-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'geography', $t$Pobitora (Morigaon, 1987): famous for one-horned rhinos.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$The other sanctuaries are Panidihing Bird Sanctuary, Bherjan-Borajan-Padumoni, Nambor, Nambor-Doigrung and East Karbi Anglong.$t$ from public.content where slug = $t$wildlife-sanctuaries-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 4, 'fact_box', 'exam_fact', $t$Remember for exams: Assam has 17 wildlife sanctuaries; Hoollongapar is the gibbon sanctuary; Pobitora is a rhino sanctuary.$t$ from public.content where slug = $t$wildlife-sanctuaries-of-assam$t$ on conflict do nothing;
