insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$বাকী অভয়াৰণ্যকেইখন হ'ল পানীদিহিং পক্ষী অভয়াৰণ্য, ভেৰজান-বৰজান-পদুমণি, নামবৰ, নামবৰ-দৈগ্ৰুং আৰু পূব কাৰ্বি আংলং।$t$ from public.content where slug = $t$wildlife-sanctuaries-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 4, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: অসমত ১৭ খন বন্যপ্ৰাণী অভয়াৰণ্য; হোলোঙাপাৰ হলৌ বান্দৰৰ অভয়াৰণ্য; পবিতৰা গঁড়ৰ অভয়াৰণ্য।$t$ from public.content where slug = $t$wildlife-sanctuaries-of-assam$t$ on conflict do nothing;
