insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 2, 'paragraph', 'normal', $t$Several parks of Assam are also {{term:tiger-reserve|tiger reserves}} under Project Tiger:$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
