insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 5, 'paragraph', 'normal', $t$Manas was declared a {{term:biosphere-reserve|biosphere reserve}} in 1989. Dibru-Saikhowa is Assam's other biosphere reserve.$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
