insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 4, 'heading', 'normal', $t$জৈৱমণ্ডল সংৰক্ষিত ক্ষেত্ৰ$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 5, 'paragraph', 'normal', $t$১৯৮৯ চনত মানাহক {{term:biosphere-reserve|জৈৱমণ্ডল সংৰক্ষিত ক্ষেত্ৰ}} ঘোষণা কৰা হয়। ডিব্ৰু-চৈখোৱা অসমৰ আনখন জৈৱমণ্ডল সংৰক্ষিত ক্ষেত্ৰ।$t$ from public.content where slug = $t$reserves-and-wetlands$t$ on conflict do nothing;
