insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 6, 'paragraph', 'normal', $t$চাহ আটাইতকৈ গুৰুত্বপূৰ্ণ বাণিজ্যিক শস্য। আন শস্যৰ ভিতৰত আছে মৰাপাট, সৰিয়হ, মাহজাতীয় শস্য, কুঁহিয়াৰ, শাক-পাচলি আৰু ফল-মূল।$t$ from public.content where slug = $t$agriculture-and-crops$t$ on conflict do nothing;
