insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Oil and natural gas$t$, $t$Digboi, Asia's first refinery, and the four refineries of Assam.$t$, 'draft', $t$Digboi Refinery, Wikipedia: https://en.wikipedia.org/wiki/Digboi_Refinery
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Oil was first found by accident in the Digboi area in 1867, while a railway line was being laid. Drilling for oil began in 1889.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'event', $t$The Digboi {{term:refinery}} was started by the Assam Oil Company and commissioned on 11 December 1901. It is Asia's first refinery and India's oldest refinery still working.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 3, 'heading', 'normal', $t$Refineries of Assam$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 4, 'list', 'verified_fact', $t$Digboi (Tinsukia district), 1901
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$Together the four refineries can process about 7 million tonnes of {{term:crude-oil|crude oil}} a year. The oil and gas fields are in the districts of Upper Assam.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 6, 'fact_box', 'exam_fact', $t$Remember for exams: Digboi refinery, 1901, Asia's first; drilling began 1889; Assam has 4 refineries.$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
