insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$১৮৬৭ চনত ৰেলপথ নিৰ্মাণৰ সময়ত ডিগবৈ অঞ্চলত আকস্মিকভাৱে প্ৰথম তেল পোৱা যায়। ১৮৮৯ চনত তেলৰ বাবে খনন আৰম্ভ হয়।$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'event', $t$আসাম অইল কোম্পানীয়ে আৰম্ভ কৰা ডিগবৈ {{term:refinery|শোধনাগাৰ}} ১৯০১ চনৰ ১১ ডিচেম্বৰত চালু হয়। ই এছিয়াৰ প্ৰথম শোধনাগাৰ আৰু এতিয়াও চলি থকা ভাৰতৰ আটাইতকৈ পুৰণি শোধনাগাৰ।$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
