insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$চাৰিওটা শোধনাগাৰে একেলগে বছৰি প্ৰায় ৭০ লাখ টন {{term:crude-oil|খাৰুৱা তেল}} শোধন কৰিব পাৰে। তেল আৰু গেছৰ ক্ষেত্ৰসমূহ উজনি অসমৰ জিলাসমূহত আছে।$t$ from public.content where slug = $t$oil-and-natural-gas$t$ on conflict do nothing;
