insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The {{term:governor}} is the constitutional head of Assam, appointed by the President of India. The real work of government is done by the {{term:chief-minister|Chief Minister}} and the {{term:council-of-ministers|Council of Ministers}}, who answer to the Assembly. The seat of government is {{term:dispur|Dispur}}.$t$ from public.content where slug = $t$governor-cm-ministers$t$ on conflict do nothing;
