insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t${{term:governor|ৰাজ্যপাল}} অসমৰ সাংবিধানিক মুৰব্বী, যাক ভাৰতৰ ৰাষ্ট্ৰপতিয়ে নিযুক্তি দিয়ে। চৰকাৰৰ প্ৰকৃত কাম {{term:chief-minister|মুখ্যমন্ত্ৰী}} আৰু {{term:council-of-ministers|মন্ত্ৰিপৰিষদে}} কৰে, যিসকল বিধানসভাৰ ওচৰত দায়বদ্ধ। চৰকাৰৰ আসন {{term:dispur|দিশপুৰ}}।$t$ from public.content where slug = $t$governor-cm-ministers$t$ on conflict do nothing;
