insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Assam Legislative Assembly has 126 members, each elected from one constituency for five years. It meets in the Assembly complex at Dispur.$t$ from public.content where slug = $t$assam-legislative-assembly$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$Assam's legislature is {{term:unicameral}}: the Legislative Council was abolished in 1952, so only the Assembly remains.$t$ from public.content where slug = $t$assam-legislative-assembly$t$ on conflict do nothing;
