insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসম বিধানসভাৰ সদস্য ১২৬ গৰাকী, প্ৰতিগৰাকী এটা সমষ্টিৰ পৰা পাঁচ বছৰৰ বাবে নিৰ্বাচিত। ইয়াৰ অধিৱেশন দিশপুৰৰ বিধানসভা চৌহদত বহে।$t$ from public.content where slug = $t$assam-legislative-assembly$t$ on conflict do nothing;
