insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The {{term:sixth-schedule|Sixth Schedule}} of the Constitution applies to tribal areas in four states: Assam, Meghalaya, Tripura and Mizoram. These areas are governed by elected {{term:autonomous-council|autonomous councils}}.$t$ from public.content where slug = $t$sixth-schedule-councils$t$ on conflict do nothing;
