insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$Christians in Assam are found mostly among the tribal communities.$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t${{term:scheduled-tribe|Scheduled Tribes}} make up about 12.45% and {{term:scheduled-caste|Scheduled Castes}} about 7.15% of the population.$t$ from public.content where slug = $t$population-census-2011$t$ on conflict do nothing;
