insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$জনসংখ্যা (লোকপিয়ল ২০১১)$t$, $t$অসমত কিমান মানুহ বাস কৰে, আৰু ৰাজ্যখনৰ ধৰ্মীয় গাঁথনি।$t$, 'draft', $t$Assam at a Glance 2025, Directorate of Economics and Statistics, Government of Assam: https://des.assam.gov.in/sites/default/files/swf_utility_folder/departments/ecostat_medhassu_in_oid_3/this_comm/assam_at_a_glance_-_2025.pdf
