insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Communities and tribes of Assam$t$, $t$The many peoples of Assam, in the plains and the hills.$t$, 'draft', $t$Demographics of Assam, Wikipedia: https://en.wikipedia.org/wiki/Demographics_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam is home to many communities with their own languages, festivals and dress. This is why it is often called a meeting place of cultures.$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Tribal communities$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$Major {{term:scheduled-tribe|tribal communities}} include the Bodo, Mising, Karbi, Rabha, Dimasa, Tiwa, Deori and Sonowal Kachari. The Bodos are the largest plains tribe, and the Karbis and Dimasas live mainly in the hill districts.$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$Tribal areas in the hills and in Bodoland have self-government under the {{term:sixth-schedule|Sixth Schedule}}.$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 5, 'heading', 'normal', $t$Other communities$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 6, 'paragraph', 'normal', $t$Other important groups include the Ahoms, the Koch-Rajbongshis, the Tea tribes (Adivasi) who came to work in the tea gardens, the Assamese Muslims, and the Bengali-speaking people of the Barak Valley.$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: the Bodos are the largest plains tribe of Assam; Karbis and Dimasas live mainly in the hills.$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ জনগোষ্ঠী আৰু জনজাতিসমূহ$t$, $t$সমভূমি আৰু পাহাৰৰ অসমৰ বহুতো জনগোষ্ঠী।$t$, 'draft', $t$Demographics of Assam, Wikipedia: https://en.wikipedia.org/wiki/Demographics_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসম নিজা ভাষা, উৎসৱ আৰু সাজ-পাৰ থকা বহুতো জনগোষ্ঠীৰ ঘৰ। সেইবাবেই ইয়াক প্ৰায়ে বিভিন্ন সংস্কৃতিৰ মিলনভূমি বুলি কোৱা হয়।$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$জনজাতীয় সম্প্ৰদায়$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$প্ৰধান {{term:scheduled-tribe|জনজাতীয় সম্প্ৰদায়ৰ}} ভিতৰত আছে বড়ো, মিচিং, কাৰ্বি, ৰাভা, ডিমাচা, তিৱা, দেউৰী আৰু সোণোৱাল কছাৰী। বড়োসকল আটাইতকৈ ডাঙৰ সমভূমিৰ জনজাতি, আৰু কাৰ্বি আৰু ডিমাচাসকল মূলতঃ পাহাৰীয়া জিলাত বাস কৰে।$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'normal', $t$পাহাৰ আৰু বড়োলেণ্ডৰ জনজাতীয় অঞ্চলসমূহে {{term:sixth-schedule|ষষ্ঠ অনুসূচীৰ}} অধীনত স্বায়ত্তশাসন লাভ কৰিছে।$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 5, 'heading', 'normal', $t$অন্যান্য জনগোষ্ঠী$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 6, 'paragraph', 'normal', $t$আন গুৰুত্বপূৰ্ণ গোটসমূহৰ ভিতৰত আছে আহোম, কোচ-ৰাজবংশী, চাহ বাগিচাত কাম কৰিবলৈ অহা চাহ জনগোষ্ঠী (আদিবাসী), অসমীয়া মুছলমান, আৰু বৰাক উপত্যকাৰ বাংলাভাষী লোকসকল।$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: বড়োসকল অসমৰ আটাইতকৈ ডাঙৰ সমভূমিৰ জনজাতি; কাৰ্বি আৰু ডিমাচাসকল মূলতঃ পাহাৰত থাকে।$t$ from public.content where slug = $t$communities-of-assam$t$ on conflict do nothing;
