insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assamese is the main language of Assam. Assamese and Bodo are {{term:official-language|official languages}} of the state, and Bengali is an official language in the districts of the Barak Valley.$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$Assamese was made the official language by the Assam Official Language Act of 1960.$t$ from public.content where slug = $t$languages-of-assam$t$ on conflict do nothing;
