insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Major bridges of Assam$t$, $t$Saraighat, Bogibeel, Dhola-Sadiya and Kolia Bhomora: the bridges that join Assam's two banks.$t$, 'draft', $t$Saraighat Bridge, Wikipedia: https://en.wikipedia.org/wiki/Saraighat_Bridge
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Brahmaputra and its tributaries divide Assam into north and south banks, so bridges are vital for travel and trade.$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Saraighat Bridge (1962)$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'verified_fact', $t$The Saraighat Bridge joins Guwahati and North Guwahati. Completed in 1962, it was the first {{term:road-cum-rail-bridge|road-cum-rail bridge}} of its kind across the Brahmaputra in Assam. It is 1,298 metres long. A New Saraighat Bridge was opened beside it in January 2017.$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 4, 'heading', 'normal', $t$Bogibeel Bridge (2018)$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'verified_fact', $t$The Bogibeel Bridge over the Brahmaputra joins Dibrugarh and Dhemaji. It is a {{term:double-decker-bridge|double-decker}} bridge, with two railway lines below and a three-lane road above, and is 4.94 km long. Its foundation was laid in January 1997, and Prime Minister Narendra Modi inaugurated it on 25 December 2018. It is the longest road-cum-rail bridge in India.$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h3', 6, 'heading', 'normal', $t$Dhola-Sadiya Bridge, Bhupen Hazarika Setu (2017)$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'verified_fact', $t$The Dhola-Sadiya Bridge crosses the Lohit, a {{term:tributary}} of the Brahmaputra, in Tinsukia district. It is 9.15 km long and was opened on 26 May 2017. It is named after Bhupen Hazarika and gives easier access to Arunachal Pradesh.$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h4', 8, 'heading', 'normal', $t$Kolia Bhomora Setu$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 9, 'paragraph', 'normal', $t$The 3.015 km Kolia Bhomora Setu over the Brahmaputra links Tezpur with Silghat in Nagaon district. It is named after the Ahom general Kalia Bhomora Borphukan.$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 10, 'fact_box', 'exam_fact', $t$Remember for exams: Saraighat 1962; Dhola-Sadiya (Bhupen Hazarika Setu) 2017, 9.15 km; Bogibeel 2018, longest road-cum-rail bridge in India.$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ প্ৰধান দলংসমূহ$t$, $t$শৰাইঘাট, বগীবিল, ঢোলা-শদিয়া আৰু কলীয়াভোমোৰা: অসমৰ দুই পাৰ সংযোগ কৰা দলংসমূহ।$t$, 'draft', $t$Saraighat Bridge, Wikipedia: https://en.wikipedia.org/wiki/Saraighat_Bridge
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$ব্ৰহ্মপুত্ৰ আৰু ইয়াৰ উপনৈসমূহে অসমক উত্তৰ আৰু দক্ষিণ পাৰত ভগাই ৰাখিছে, সেয়েহে যাতায়াত আৰু বাণিজ্যৰ বাবে দলং অতি গুৰুত্বপূৰ্ণ।$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 2, 'heading', 'normal', $t$শৰাইঘাট দলং (১৯৬২)$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'verified_fact', $t$শৰাইঘাট দলঙে গুৱাহাটী আৰু উত্তৰ গুৱাহাটী সংযোগ কৰে। ১৯৬২ চনত সম্পূৰ্ণ হোৱা এই দলং অসমত ব্ৰহ্মপুত্ৰৰ ওপৰত এনেধৰণৰ প্ৰথম {{term:road-cum-rail-bridge|পথ-ৰেল দলং}}। ইয়াৰ দৈৰ্ঘ্য ১,২৯৮ মিটাৰ। ২০১৭ চনৰ জানুৱাৰীত ইয়াৰ কাষতে নতুন শৰাইঘাট দলং মুকলি কৰা হয়।$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h2', 4, 'heading', 'normal', $t$বগীবিল দলং (২০১৮)$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'verified_fact', $t$ব্ৰহ্মপুত্ৰৰ ওপৰৰ বগীবিল দলঙে ডিব্ৰুগড় আৰু ধেমাজি সংযোগ কৰে। ই এখন {{term:double-decker-bridge|দুমহলীয়া}} দলং, তলত দুটা ৰেললাইন আৰু ওপৰত তিনি লেনৰ পথ, আৰু ইয়াৰ দৈৰ্ঘ্য ৪.৯৪ কিমি। ১৯৯৭ চনৰ জানুৱাৰীত ইয়াৰ আধাৰশিলা স্থাপন কৰা হয়, আৰু ২০১৮ চনৰ ২৫ ডিচেম্বৰত প্ৰধানমন্ত্ৰী নৰেন্দ্ৰ মোদীয়ে ইয়াৰ উদ্বোধন কৰে। ই ভাৰতৰ দীৰ্ঘতম পথ-ৰেল দলং।$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h3', 6, 'heading', 'normal', $t$ঢোলা-শদিয়া দলং, ভূপেন হাজৰিকা সেতু (২০১৭)$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'verified_fact', $t$ঢোলা-শদিয়া দলঙে তিনিচুকীয়া জিলাত ব্ৰহ্মপুত্ৰৰ {{term:tributary|উপনৈ}} লুইত পাৰ হৈছে। ইয়াৰ দৈৰ্ঘ্য ৯.১৫ কিমি আৰু ই ২০১৭ চনৰ ২৬ মে'ত মুকলি হয়। ইয়াক ভূপেন হাজৰিকাৰ নামেৰে নামকৰণ কৰা হৈছে আৰু ই অৰুণাচল প্ৰদেশলৈ যাতায়াত সহজ কৰিছে।$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h4', 8, 'heading', 'normal', $t$কলীয়াভোমোৰা সেতু$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 9, 'paragraph', 'normal', $t$ব্ৰহ্মপুত্ৰৰ ওপৰৰ ৩.০১৫ কিমি দীঘল কলীয়াভোমোৰা সেতুৱে তেজপুৰক নগাঁও জিলাৰ শিলঘাটৰ সৈতে সংযোগ কৰে। ইয়াক আহোম সেনাপতি কলীয়াভোমোৰা বৰফুকনৰ নামেৰে নামকৰণ কৰা হৈছে।$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 10, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: শৰাইঘাট ১৯৬২; ঢোলা-শদিয়া (ভূপেন হাজৰিকা সেতু) ২০১৭, ৯.১৫ কিমি; বগীবিল ২০১৮, ভাৰতৰ দীৰ্ঘতম পথ-ৰেল দলং।$t$ from public.content where slug = $t$major-bridges-of-assam$t$ on conflict do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$district$t$, $t$District$t$, $t$জিলা$t$, $t$The main unit of administration within a state, headed by a Deputy Commissioner in Assam.$t$, $t$ৰাজ্যৰ ভিতৰৰ প্ৰশাসনৰ মূল একক; অসমত ইয়াৰ মুৰব্বী উপায়ুক্ত।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$deputy-commissioner$t$, $t$Deputy Commissioner$t$, $t$উপায়ুক্ত$t$, $t$The officer in charge of a district in Assam, responsible for law and order, revenue and development.$t$, $t$অসমত এখন জিলাৰ দায়িত্বত থকা বিষয়া, যি আইন-শৃংখলা, ৰাজহ আৰু উন্নয়নৰ বাবে দায়বদ্ধ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$co-district$t$, $t$Co-district$t$, $t$সহ-জিলা$t$, $t$An administrative unit inside a district that brings government services closer to people. It is not a separate district.$t$, $t$চৰকাৰী সেৱা মানুহৰ ওচৰলৈ নিবলৈ জিলাৰ ভিতৰত গঠন কৰা প্ৰশাসনিক একক। ই সুকীয়া জিলা নহয়।$t$) on conflict (slug) do nothing;
