insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Districts of Assam: overview$t$, $t$All 35 districts of Assam, and how the number grew over the years.$t$, 'draft', $t$List of districts of Assam, Wikipedia: https://en.wikipedia.org/wiki/List_of_districts_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam has 35 {{term:district|districts}}. Each is headed by a {{term:deputy-commissioner|Deputy Commissioner}} and divided into {{term:sub-division|sub-divisions}}.$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$The 35 districts (A to Z)$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'geography', $t$Bajali, Baksa, Barpeta, Biswanath, Bongaigaon, Cachar, Charaideo, Chirang, Darrang, Dhemaji, Dhubri, Dibrugarh, Dima Hasao, Goalpara, Golaghat, Hailakandi, Hojai, Jorhat, Kamrup, Kamrup Metropolitan, Karbi Anglong, Kokrajhar, Lakhimpur, Majuli, Morigaon, Nagaon, Nalbari, Sivasagar, Sonitpur, South Salmara-Mankachar, Sribhumi (Karimganj), Tamulpur, Tinsukia, Udalguri, West Karbi Anglong$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 4, 'heading', 'normal', $t$How the number of districts grew$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 5, 'list', 'event', $t$1983: Barpeta, Sonitpur, Jorhat, Dhubri, Kokrajhar and Karimganj districts are created.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 6, 'paragraph', 'normal', $t$Karimganj district has been renamed Sribhumi. Assam has also set up {{term:co-district|co-districts}} to bring offices closer to people; these are not separate districts.$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$A separate page for each district will be added later.$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 8, 'fact_box', 'exam_fact', $t$Remember for exams: 35 districts; Majuli is the first river island district (2016); Tamulpur is the 35th district.$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ জিলাসমূহ: এক চমু আভাস$t$, $t$অসমৰ ৩৫ খন জিলা, আৰু বছৰৰ পিছত বছৰ জিলাৰ সংখ্যা কেনেকৈ বাঢ়িল।$t$, 'draft', $t$List of districts of Assam, Wikipedia: https://en.wikipedia.org/wiki/List_of_districts_of_Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসমত ৩৫ খন {{term:district|জিলা}} আছে। প্ৰতিখন জিলাৰ মুৰব্বী এগৰাকী {{term:deputy-commissioner|উপায়ুক্ত}} আৰু প্ৰতিখন জিলা কেইটামান {{term:sub-division|মহকুমাত}} বিভক্ত।$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
