insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'geography', $t$বজালী, বাক্সা, বৰপেটা, বিশ্বনাথ, বঙাইগাঁও, কাছাৰ, চৰাইদেউ, চিৰাং, দৰং, ধেমাজি, ধুবুৰী, ডিব্ৰুগড়, ডিমা হাছাও, গোৱালপাৰা, গোলাঘাট, হাইলাকান্দি, হোজাই, যোৰহাট, কামৰূপ, কামৰূপ মহানগৰ, কাৰ্বি আংলং, কোকৰাঝাৰ, লখিমপুৰ, মাজুলী, মৰিগাঁও, নগাঁও, নলবাৰী, শিৱসাগৰ, শোণিতপুৰ, দক্ষিণ শালমাৰা-মানকাচৰ, শ্ৰীভূমি (কৰিমগঞ্জ), তামুলপুৰ, তিনিচুকীয়া, ওদালগুৰি, পশ্চিম কাৰ্বি আংলং$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
