insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 5, 'list', 'event', $t$১৯৮৩: বৰপেটা, শোণিতপুৰ, যোৰহাট, ধুবুৰী, কোকৰাঝাৰ আৰু কৰিমগঞ্জ জিলা গঠন হয়।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 6, 'paragraph', 'normal', $t$কৰিমগঞ্জ জিলাৰ নাম সলনি কৰি শ্ৰীভূমি কৰা হৈছে। কাৰ্যালয়সমূহ মানুহৰ ওচৰলৈ নিবলৈ অসমত {{term:co-district|সহ-জিলাও}} গঠন কৰা হৈছে; এইবোৰ সুকীয়া জিলা নহয়।$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$প্ৰতিখন জিলাৰ বাবে সুকীয়া পৃষ্ঠা পিছত যোগ কৰা হ'ব।$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 8, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ৩৫ খন জিলা; মাজুলী প্ৰথম নদী দ্বীপ জিলা (২০১৬); তামুলপুৰ ৩৫ সংখ্যক জিলা।$t$ from public.content where slug = $t$districts-of-assam-overview$t$ on conflict do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$shakti-peetha$t$, $t$Shakti Peetha$t$, $t$শক্তিপীঠ$t$, $t$A holy site of the goddess Shakti. Kamakhya is one of the most important of them.$t$, $t$শক্তি দেৱীৰ পবিত্ৰ তীৰ্থস্থান। কামাখ্যা তাৰে অন্যতম গুৰুত্বপূৰ্ণ।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$ambubachi-mela$t$, $t$Ambubachi Mela$t$, $t$অম্বুবাচী মেলা$t$, $t$The yearly festival at Kamakhya Temple, attended by large numbers of pilgrims.$t$, $t$কামাখ্যা মন্দিৰত প্ৰতি বছৰে হোৱা মেলা, য'ত বহুসংখ্যক তীৰ্থযাত্ৰী সমাগম হয়।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$erosion$t$, $t$Erosion$t$, $t$খহনীয়া$t$, $t$The wearing away of land by river water. It has made Majuli much smaller.$t$, $t$নদীৰ পানীয়ে মাটি খহাই নিয়া প্ৰক্ৰিয়া। ইয়াৰ ফলত মাজুলী বহুত সৰু হৈছে।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$dol$t$, $t$Dol$t$, $t$দ'ল$t$, $t$A temple built in the Ahom period, such as the Shiva Dol at Sivasagar.$t$, $t$আহোম যুগত নিৰ্মিত মন্দিৰ, যেনে শিৱসাগৰৰ শিৱদ'ল।$t$) on conflict (slug) do nothing;
insert into public.terms (slug, term_en, term_as, meaning_en, meaning_as) values ($t$pilgrimage$t$, $t$Pilgrimage$t$, $t$তীৰ্থযাত্ৰা$t$, $t$A journey to a holy place for religious reasons.$t$, $t$ধৰ্মীয় কাৰণত পবিত্ৰ স্থানলৈ কৰা যাত্ৰা।$t$) on conflict (slug) do nothing;
insert into public.content (slug, kind, category_id, position) select $t$kamakhya-temple$t$, 'gk_chapter', id, 1 from public.categories where slug = $t$places$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Kamakhya Temple$t$, $t$The famous Shakti temple on Nilachal Hill in Guwahati.$t$, 'draft', $t$Kamakhya Temple, Wikipedia: https://en.wikipedia.org/wiki/Kamakhya_Temple$t$, date '2026-11-24' from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'heritage', $t$The Kamakhya Temple stands on Nilachal Hill in Guwahati. It is one of the oldest and most important {{term:shakti-peetha|Shakti Peethas}} in India, and a centre of Tantric worship.$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'event', $t$The temple was rebuilt by the Koch king Nara Narayan, who completed the work in 1565; his brother Chilarai supervised the main temple.$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'normal', $t$Its style, with a rounded dome on a cross-shaped base, is called the Nilachal type.$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 4, 'paragraph', 'normal', $t$Every year the {{term:ambubachi-mela|Ambubachi Mela}} draws pilgrims from all over India.$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: Kamakhya on Nilachal Hill; rebuilt by Nara Narayan in 1565; Ambubachi Mela.$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$কামাখ্যা মন্দিৰ$t$, $t$গুৱাহাটীৰ নীলাচল পাহাৰৰ বিখ্যাত শক্তি মন্দিৰ।$t$, 'draft', $t$Kamakhya Temple, Wikipedia: https://en.wikipedia.org/wiki/Kamakhya_Temple$t$, date '2026-11-24' from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'heritage', $t$কামাখ্যা মন্দিৰ গুৱাহাটীৰ নীলাচল পাহাৰত অৱস্থিত। ই ভাৰতৰ আটাইতকৈ পুৰণি আৰু গুৰুত্বপূৰ্ণ {{term:shakti-peetha|শক্তিপীঠসমূহৰ}} এটা, আৰু তান্ত্ৰিক উপাসনাৰ কেন্দ্ৰ।$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'event', $t$কোচ ৰজা নৰনাৰায়ণে মন্দিৰটো পুনৰ নিৰ্মাণ কৰে আৰু ১৫৬৫ চনত কাম সম্পূৰ্ণ কৰে; তেওঁৰ ভাতৃ চিলাৰায়ে মূল মন্দিৰৰ কামৰ তত্ত্বাৱধান কৰে।$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'normal', $t$ক্ৰছ আকৃতিৰ ভেটিৰ ওপৰত গোলাকাৰ গম্বুজ থকা ইয়াৰ স্থাপত্য শৈলীক নীলাচল শৈলী বোলা হয়।$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 4, 'paragraph', 'normal', $t$প্ৰতি বছৰে {{term:ambubachi-mela|অম্বুবাচী মেলাই}} সমগ্ৰ ভাৰতৰ পৰা তীৰ্থযাত্ৰী আকৰ্ষণ কৰে।$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: কামাখ্যা নীলাচল পাহাৰত; ১৫৬৫ চনত নৰনাৰায়ণে পুনৰ নিৰ্মাণ কৰে; অম্বুবাচী মেলা।$t$ from public.content where slug = $t$kamakhya-temple$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$majuli$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$places$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Majuli$t$, $t$The river island of the Brahmaputra, home of the Sattras.$t$, 'draft', $t$Majuli, Wikipedia: https://en.wikipedia.org/wiki/Majuli$t$, date '2026-11-24' from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'geography', $t$Majuli is a {{term:river-island|river island}} in the Brahmaputra. It is often called the largest river island in the world. In 2016 it became the first island in India to be made a district.$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$Because of {{term:erosion}}, Majuli has shrunk from about 1,255 sq km in the early 20th century to about 880 sq km in 2024.$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'heritage', $t$Majuli is the main centre of the {{term:sattra|Sattra}} tradition started by Sankardev. Of the 65 Sattras once here, 23 are still active, including the Garamur Sattra.$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 4, 'paragraph', 'normal', $t$The Mising people are the largest community on the island, making up about 41 percent of its population.$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: Majuli became a district in 2016, India's first island district.$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$মাজুলী$t$, $t$সত্ৰৰ ঘৰ, ব্ৰহ্মপুত্ৰৰ নদী দ্বীপ।$t$, 'draft', $t$Majuli, Wikipedia: https://en.wikipedia.org/wiki/Majuli$t$, date '2026-11-24' from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'geography', $t$মাজুলী ব্ৰহ্মপুত্ৰৰ এখন {{term:river-island|নদী দ্বীপ}}। ইয়াক প্ৰায়ে পৃথিৱীৰ বৃহত্তম নদী দ্বীপ বুলি কোৱা হয়। ২০১৬ চনত ই ভাৰতৰ প্ৰথম দ্বীপ জিলা হয়।$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t${{term:erosion|খহনীয়াৰ}} ফলত বিংশ শতিকাৰ আৰম্ভণিৰ প্ৰায় ১,২৫৫ বৰ্গ কিমিৰ পৰা ২০২৪ চনত মাজুলী প্ৰায় ৮৮০ বৰ্গ কিমিলৈ সৰু হৈছে।$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'heritage', $t$মাজুলী শংকৰদেৱে আৰম্ভ কৰা {{term:sattra|সত্ৰ}} পৰম্পৰাৰ মূল কেন্দ্ৰ। এসময়ত ইয়াত থকা ৬৫ খন সত্ৰৰ ২৩ খন এতিয়াও সক্ৰিয়, তাৰ ভিতৰত গড়মূৰ সত্ৰ অন্যতম।$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 4, 'paragraph', 'normal', $t$মিচিং লোকসকল দ্বীপটোৰ আটাইতকৈ ডাঙৰ জনগোষ্ঠী, যিসকল ইয়াৰ জনসংখ্যাৰ প্ৰায় ৪১ শতাংশ।$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ২০১৬ চনত মাজুলী জিলা হয়, ভাৰতৰ প্ৰথম দ্বীপ জিলা।$t$ from public.content where slug = $t$majuli$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$sivasagar-monuments$t$, 'gk_chapter', id, 3 from public.categories where slug = $t$places$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Sivasagar and its monuments$t$, $t$The old Ahom capital Rangpur, the great tank and the Shiva Dol.$t$, 'draft', $t$Sivasagar, Wikipedia: https://en.wikipedia.org/wiki/Sivasagar
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Sivasagar was once Rangpur, a capital of the Ahom kingdom in the 18th century. It is well known for its Ahom palaces and monuments.$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'heritage', $t$The great tank of Sivasagar (Borpukhuri) was dug in 1733 by the Ahom queen Ambika Devi and covers 257 acres. The Shiva {{term:dol}} stands on its bank, and the town takes its name from it.$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'heritage', $t$The Rang Ghar, a two-storeyed pavilion from which Ahom kings watched games and sports, was built of brick by King Pramatta Singha (1744 to 1751).$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 4, 'fact_box', 'exam_fact', $t$Remember for exams: Sivasagar tank dug in 1733 by Queen Ambika Devi; Rang Ghar built by Pramatta Singha.$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$শিৱসাগৰ আৰু ইয়াৰ কীৰ্তিচিহ্নসমূহ$t$, $t$আহোমৰ পুৰণি ৰাজধানী ৰংপুৰ, বৰপুখুৰী আৰু শিৱদ'ল।$t$, 'draft', $t$Sivasagar, Wikipedia: https://en.wikipedia.org/wiki/Sivasagar
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$শিৱসাগৰ এসময়ত ৰংপুৰ আছিল, অষ্টাদশ শতিকাত আহোম ৰাজ্যৰ এখন ৰাজধানী। ই আহোম ৰাজকাৰেং আৰু কীৰ্তিচিহ্নৰ বাবে জনাজাত।$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'heritage', $t$শিৱসাগৰৰ বৰপুখুৰী ১৭৩৩ চনত আহোম ৰাণী অম্বিকা দেৱীয়ে খান্দিছিল আৰু ইয়াৰ আয়তন ২৫৭ একৰ। ইয়াৰ পাৰত শিৱ{{term:dol|দ'ল}} আছে, আৰু নগৰখনৰ নাম ইয়াৰ পৰাই আহিছে।$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'heritage', $t$আহোম ৰজাসকলে খেল-ধেমালি চোৱা দুমহলীয়া ৰংঘৰ ৰজা প্ৰমত্ত সিংহই (১৭৪৪ ৰ পৰা ১৭৫১) ইটাৰে নিৰ্মাণ কৰিছিল।$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 4, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ১৭৩৩ চনত ৰাণী অম্বিকা দেৱীয়ে শিৱসাগৰ পুখুৰী খান্দে; প্ৰমত্ত সিংহই ৰংঘৰ নিৰ্মাণ কৰে।$t$ from public.content where slug = $t$sivasagar-monuments$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$hajo$t$, 'gk_chapter', id, 4 from public.categories where slug = $t$places$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Hajo$t$, $t$A pilgrimage town sacred to Hindus, Buddhists and Muslims.$t$, 'draft', $t$Hajo, Wikipedia: https://en.wikipedia.org/wiki/Hajo
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Hajo is a town in Kamrup district, about 25 km northwest of Guwahati on the Brahmaputra. It is a meeting point of Hindus, Buddhists and Muslims, and an important place of {{term:pilgrimage}}.$t$ from public.content where slug = $t$hajo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'heritage', $t$Hayagriva Madhava Temple, on Monikut hill: the present temple was built by King Raghudev Narayan in 1583. Buddhists also visit it.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 3, 'fact_box', 'exam_fact', $t$Remember for exams: Hajo, Kamrup district; Hayagriva Madhava Temple (1583); Poa Mecca.$t$ from public.content where slug = $t$hajo$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$হাজো$t$, $t$হিন্দু, বৌদ্ধ আৰু মুছলমানৰ পবিত্ৰ তীৰ্থস্থান।$t$, 'draft', $t$Hajo, Wikipedia: https://en.wikipedia.org/wiki/Hajo
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$হাজো কামৰূপ জিলাৰ এখন নগৰ, ব্ৰহ্মপুত্ৰৰ পাৰত গুৱাহাটীৰ প্ৰায় ২৫ কিমি উত্তৰ-পশ্চিমে। ই হিন্দু, বৌদ্ধ আৰু মুছলমানৰ মিলনস্থল, আৰু এক গুৰুত্বপূৰ্ণ {{term:pilgrimage|তীৰ্থস্থান}}।$t$ from public.content where slug = $t$hajo$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'heritage', $t$মণিকূট পাহাৰৰ হয়গ্ৰীৱ মাধৱ মন্দিৰ: বৰ্তমানৰ মন্দিৰটো ১৫৮৩ চনত ৰজা ৰঘুদেৱ নাৰায়ণে নিৰ্মাণ কৰে। বৌদ্ধসকলেও ইয়ালৈ আহে।
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 3, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: হাজো, কামৰূপ জিলা; হয়গ্ৰীৱ মাধৱ মন্দিৰ (১৫৮৩); পোৱামক্কা।$t$ from public.content where slug = $t$hajo$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$tezpur$t$, 'gk_chapter', id, 5 from public.categories where slug = $t$places$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Tezpur$t$, $t$The city of Usha and Aniruddha, with Agnigarh and the Da Parbatia temple ruins.$t$, 'draft', $t$Tezpur, Wikipedia: https://en.wikipedia.org/wiki/Tezpur
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Tezpur is a city in Sonitpur district on the north bank of the Brahmaputra, about 175 km northeast of Guwahati. Its name is often explained as 'city of blood', from a legend about a great battle here.$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'heritage', $t$The legend tells of Usha, daughter of the Asura king Banasura, and her love for Aniruddha, grandson of Krishna. Agnigarh, a hillock on the river bank, is said to be where Usha was kept, surrounded by fire.$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'heritage', $t$At Da Parbatia, near Tezpur, a stone door frame from a temple of about the 6th century was dug up in 1924. It is one of the oldest pieces of sculpture in Assam.$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 4, 'paragraph', 'normal', $t$Jyoti Prasad Agarwala lived and died in Tezpur. The Kolia Bhomora Setu links Tezpur with the south bank.$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: Tezpur, Agnigarh (Usha-Aniruddha legend); Da Parbatia door frame (6th century).$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$তেজপুৰ$t$, $t$উষা আৰু অনিৰুদ্ধৰ নগৰ, অগ্নিগড় আৰু দহপৰ্বতীয়াৰ মন্দিৰৰ ধ্বংসাৱশেষ।$t$, 'draft', $t$Tezpur, Wikipedia: https://en.wikipedia.org/wiki/Tezpur
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$তেজপুৰ ব্ৰহ্মপুত্ৰৰ উত্তৰ পাৰৰ শোণিতপুৰ জিলাৰ এখন নগৰ, গুৱাহাটীৰ প্ৰায় ১৭৫ কিমি উত্তৰ-পূবে। ইয়াত হোৱা এক ভয়ংকৰ যুদ্ধৰ কাহিনীৰ পৰা ইয়াৰ নামৰ অৰ্থ প্ৰায়ে 'তেজৰ নগৰ' বুলি ব্যাখ্যা কৰা হয়।$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'heritage', $t$কাহিনীটো অসুৰ ৰজা বাণাসুৰৰ কন্যা উষা আৰু কৃষ্ণৰ নাতি অনিৰুদ্ধৰ প্ৰেমৰ। নদীৰ পাৰৰ টিলা অগ্নিগড়তে জুইৰে আগুৰি উষাক ৰখা হৈছিল বুলি কোৱা হয়।$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'heritage', $t$তেজপুৰৰ ওচৰৰ দহপৰ্বতীয়াত ১৯২৪ চনত প্ৰায় ষষ্ঠ শতিকাৰ এটা মন্দিৰৰ শিলৰ দুৱাৰমুখ খান্দি উলিওৱা হয়। ই অসমৰ আটাইতকৈ পুৰণি ভাস্কৰ্যসমূহৰ এটা।$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 4, 'paragraph', 'normal', $t$জ্যোতিপ্ৰসাদ আগৰৱালাই তেজপুৰত বাস কৰিছিল আৰু তাতেই তেওঁৰ মৃত্যু হয়। কলীয়াভোমোৰা সেতুৱে তেজপুৰক দক্ষিণ পাৰৰ সৈতে সংযোগ কৰে।$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: তেজপুৰ, অগ্নিগড় (উষা-অনিৰুদ্ধৰ কাহিনী); দহপৰ্বতীয়াৰ দুৱাৰমুখ (ষষ্ঠ শতিকা)।$t$ from public.content where slug = $t$tezpur$t$ on conflict do nothing;
